@SpringBootTest
class FirmwareDualBootConcurrencyTest {

    @TestConfiguration
    static class TestClockConfig {

        @Bean
        @Primary
        MutableClock mutableClock() {
            return new MutableClock(Instant.parse("2026-10-04T00:00:00Z"));
        }
    }

